#[test]
fn sampled_objective_and_ensemble_regressions_match_native() {
    let inputs: Value =
        serde_json::from_str(include_str!("fixtures/prediction_boosting.json")).unwrap();
    let base = &inputs["cases"][0]["training"];
    let x: Vec<f64> = base["rows"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|r| r.as_array().unwrap().iter().map(|v| v.as_f64().unwrap()))
        .collect();
    let fixture: Value = serde_json::from_str(NATIVE).unwrap();
    assert_eq!(fixture.as_array().unwrap().len(), 8);
    for case in fixture.as_array().unwrap() {
        let mut pairs: Vec<(String, String)> = case["params"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| {
                (
                    k.clone(),
                    v.as_str().map_or_else(|| v.to_string(), str::to_owned),
                )
            })
            .collect();
        pairs.push(("num_iterations".into(), case["rounds"].to_string()));
        let config = Config::from_pairs(pairs).unwrap();
        let mut data = Dataset::from_dense(
            &x,
            32,
            4,
            serde_json::from_value(case["labels"].clone()).unwrap(),
            &config,
        )
        .unwrap()
        .with_weights(serde_json::from_value(base["weights"].clone()).unwrap())
        .unwrap();
        if !case["init"].is_null() {
            data = data
                .with_initial_scores(serde_json::from_value(case["init"].clone()).unwrap(), 1)
                .unwrap();
        }
        let result = Trainer::new(config).unwrap().fit(&data).unwrap();
        let raw = result.model.predict_raw_dense(&x, 32, 4).unwrap();
        for (got, want) in raw.iter().flatten().zip(
            case["raw"]
                .as_array()
                .unwrap()
                .iter()
                .flat_map(|r| r.as_array().unwrap()),
        ) {
            let want = want.as_f64().unwrap();
            assert!(
                (got - want).abs() <= 1e-12 + 1e-10 * want.abs(),
                "{}: {got} != {want}",
                case["name"]
            );
        }
        assert_eq!(
            result.model.trees().len(),
            case["trees"].as_array().unwrap().len()
        );
        for (tree, expected) in result
            .model
            .trees()
            .iter()
            .zip(case["trees"].as_array().unwrap())
        {
            let ints = |key: &str| {
                expected[key]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_str().unwrap().parse::<i64>().unwrap())
                    .collect::<Vec<_>>()
            };
            assert_eq!(
                tree.split_features()
                    .iter()
                    .map(|&i| i as i64)
                    .collect::<Vec<_>>(),
                ints("split_feature"),
                "{}",
                case["name"]
            );
            let thresholds: Vec<f64> = expected["threshold"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap().parse().unwrap())
                .collect();
            assert_eq!(tree.thresholds(), thresholds);
            assert_eq!(
                tree.left_children()
                    .iter()
                    .map(|&i| i as i64)
                    .collect::<Vec<_>>(),
                ints("left_child")
            );
            assert_eq!(
                tree.right_children()
                    .iter()
                    .map(|&i| i as i64)
                    .collect::<Vec<_>>(),
                ints("right_child")
            );
            assert_eq!(
                tree.leaf_counts()
                    .iter()
                    .map(|&i| i as i64)
                    .collect::<Vec<_>>(),
                ints("leaf_count"),
                "{} leaf counts",
                case["name"]
            );
            for (&got, want) in tree
                .leaf_values()
                .iter()
                .zip(expected["leaf_value"].as_array().unwrap())
            {
                let want = want.as_str().unwrap().parse::<f64>().unwrap();
                assert!(
                    (got - want).abs() <= 1e-12 + 1e-10 * want.abs(),
                    "{}: leaf {got} != {want}",
                    case["name"]
                );
            }
        }
        if let Some(initial) = data.initial_scores() {
            for (row, score) in raw.iter().enumerate() {
                assert!((result.training_scores[row] - score[0] - initial[row]).abs() < 1e-12);
            }
        }
    }
}
